```yaml
name: Dependabot Auto-Merge

on:
  pull_request_target:
    types: [opened, synchronize, reopened]
  workflow_run:
    workflows: ["Only CI/CT"]
    types:
      - completed

permissions:
  contents: read
  pull-requests: read
  checks: read

jobs:
  auto-merge:
    runs-on: ubuntu-latest
    if: >-
      github.event_name == 'pull_request_target' &&
      github.event.pull_request.user.login == 'dependabot[bot]'
    permissions:
      contents: write
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Dependabot metadata
        id: dependabot-metadata
        uses: dependabot/fetch-metadata@v2
        with:
          github-token: "${{ secrets.GITHUB_TOKEN }}"

      - name: Auto-merge Dependabot PRs
        uses: peter-evans/enable-pull-request-automerge@v3
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          pull-request-number: ${{ github.event.pull_request.number }}
          merge-method: squash

  validate-and-merge:
    runs-on: ubuntu-latest
    if: >-
      github.event_name == 'workflow_run' &&
      github.event.workflow_run.conclusion == 'success'
    needs: auto-merge
    permissions:
      contents: write
      pull-requests: write
      checks: read
    steps:
      - name: Wait for status propagation
        run: sleep 5

      - name: Get PR details from workflow run
        id: get-pr
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const workflowRun = github.context.payload.workflow_run;
            const pullRequests = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              head: `${workflowRun.head_repository.owner.login}:${workflowRun.head_branch}`
            });

            if (pullRequests.data.length === 0) {
              core.info('No open PRs found for this workflow run');
              return;
            }

            const pr = pullRequests.data[0];
            core.setOutput('pr-number', pr.number);
            core.setOutput('pr-author', pr.user.login);
            return pr;

      - name: Check if PR is from Dependabot
        id: check-dependabot
        if: steps.get-pr.outputs.pr-author == 'dependabot[bot]'
        run: echo "is_dependabot=true" >> $GITHUB_OUTPUT

      - name: Fetch PR checks
        if: steps.check-dependabot.outputs.is_dependabot == 'true'
        id: fetch-checks
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ steps.get-pr.outputs.pr-number }};

            // Get combined status
            const combinedStatus = await github.rest.checks.getCombinedStatusForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: context.payload.workflow_run.head_sha
            });

            // Get individual check runs
            const checkRuns = await github.rest.checks.listForRef({
              owner: context.repo.owner,
              repo: context.repo.repo,
              ref: context.payload.workflow_run.head_sha
            });

            const hasValidation = checkRuns.data.total_count > 0;
            core.setOutput('has-validation', hasValidation);

            if (!hasValidation) {
              core.warning('No validation checks found, skipping merge');
              return;
            }

            // Check for failed or cancelled checks
            const failedChecks = checkRuns.data.check_runs.filter(
              check => check.conclusion === 'failure' || check.conclusion === 'cancelled'
            );

            if (failedChecks.length > 0) {
              core.error(`Found ${failedChecks.length} failed/cancelled checks`);
              core.setOutput('has-failures', 'true');
              return;
            }

            core.setOutput('has-failures', 'false');
            core.setOutput('pr-number', prNumber);

      - name: Auto-approve PR
        if: >-
          steps.check-dependabot.outputs.is_dependabot == 'true' &&
          steps.fetch-checks.outputs.has-validation == 'true' &&
          steps.fetch-checks.outputs.has-failures == 'false'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ steps.fetch-checks.outputs.pr-number }};

            try {
              await github.rest.pulls.createReview({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: prNumber,
                event: 'APPROVE',
                body: 'Automatically approved by Dependabot auto-merge workflow'
              });
              core.info(`PR #${prNumber} approved`);
            } catch (error) {
              if (error.status === 422) {
                core.warning('PR may already be approved');
              } else {
                throw error;
              }
            }

      - name: Enable auto-merge
        if: >-
          steps.check-dependabot.outputs.is_dependabot == 'true' &&
          steps.fetch-checks.outputs.has-validation == 'true' &&
          steps.fetch-checks.outputs.has-failures == 'false'
        uses: peter-evans/enable-pull-request-automerge@v3
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          pull-request-number: ${{ steps.fetch-checks.outputs.pr-number }}
          merge-method: squash
